import type { Tools } from "../generated/tools";

type Grade = "large" | "documented" | "plain";

interface Graded {
  path: string;
  grade: Grade;
}

interface ThoughtResult {
  thoughtNumber: number;
  totalThoughts: number;
  nextThoughtNeeded: boolean;
  branches: string[];
  thoughtHistoryLength: number;
}

/** Turn the raw search/listing output into clean absolute paths. */
function parsePaths(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => line.replace(/^\[(FILE|DIR)\]\s*/, ""));
}

/** Best-effort byte size from the metadata text, falling back to source length. */
function fileSizeBytes(infoContent: string, textContent: string): number {
  const match = infoContent.match(/size["']?\s*[:=]\s*"?(\d+)/i);
  return match ? Number(match[1]) : textContent.length;
}

/** large when over 200 bytes, else documented when it carries a JSDoc block, else plain. */
function gradeModule(sizeBytes: number, text: string): Grade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordFailure(failures: string[], key: string, error: unknown) {
  failures.push(`${key}: ${String(error)}`);
}

function recordGrade(grades: Graded[], path: string, grade: Grade) {
  grades.push({ path, grade });
}

function countGrades(grades: Graded[]): Record<Grade, number> {
  const counts: Record<Grade, number> = { large: 0, documented: 0, plain: 0 };
  for (const entry of grades) {
    counts[entry.grade] += 1;
  }
  return counts;
}

function renderAudit(grades: Graded[], failures: string[], thoughts: ThoughtResult[]): string {
  const lines: string[] = ["# Repository audit", "", "## modules", ""];
  for (const entry of grades) {
    lines.push(`- ${entry.path}: ${entry.grade}`);
  }
  lines.push("", "## reasoning", "");
  for (const thought of thoughts) {
    lines.push(`- thought ${thought.thoughtNumber} of ${thought.totalThoughts} recorded`);
  }
  lines.push("");
  if (failures.length > 0) {
    lines.push("## unreadable modules", "");
    for (const failure of failures) {
      lines.push(`- ${failure}`);
    }
    lines.push("");
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [sizedListing, tree, allowedDirectories] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({}),
  ]);

  const searchResults = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const modulePaths = parsePaths(searchResults.content);

  const graded: Graded[] = [];
  const failures: string[] = [];
  let attempted = 0;

  for (const modulePath of modulePaths) {
    if (attempted >= input.maxModules) {
      break;
    }
    attempted += 1;

    let infoContent = "";
    let text = "";
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      infoContent = info.content;
      const read = await tools.fs.readTextFile({ path: modulePath });
      text = read.content;
    } catch (error) {
      recordFailure(failures, modulePath, error);
      continue;
    }

    const sizeBytes = fileSizeBytes(infoContent, text);
    const grade = gradeModule(sizeBytes, text);
    recordGrade(graded, modulePath, grade);
  }

  const thought1 = await tools.reasoning.sequentialThinking({
    thought:
      "Inventory pass: the sized listing, the recursive tree, and the allowed directories were gathered in parallel. The tree shows the module layout under the root, and the allowed-directories list confirms the audit may only touch that root.",
    thoughtNumber: 1,
    totalThoughts: 3,
    nextThoughtNeeded: true,
  });
  const thought2 = await tools.reasoning.sequentialThinking({
    thought:
      "Grading pass: for each *.ts module up to the cap, metadata was fetched and the source read. Over 200 bytes grades 'large'; otherwise 'documented' when the source contains a /** JSDoc block; otherwise 'plain'. Unreadable modules were recorded and skipped instead of failing the run.",
    thoughtNumber: 2,
    totalThoughts: 3,
    nextThoughtNeeded: true,
  });
  const thought3 = await tools.reasoning.sequentialThinking({
    thought:
      "Verification: every graded module has both a metadata sample and a source read behind it, failures are tracked separately, and the per-grade counts summarize the audit. The hypothesis holds — ready to write audit.md with the grades and the reasoning record.",
    thoughtNumber: 3,
    totalThoughts: 3,
    nextThoughtNeeded: false,
  });
  const thoughts = [thought1, thought2, thought3];

  const report = renderAudit(graded, failures, thoughts);
  const written = await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report,
  });

  const counts = countGrades(graded);

  return {
    counts,
    thoughtsRecorded: thoughts.length,
    modulesAudited: graded.length,
    failures,
  };
}

import type { Tools } from "../generated/tools";

type ModuleGrade = { path: string; grade: string };

function modulePaths(searchResult: string): string[] {
  return searchResult
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && line.endsWith(".ts"));
}

function parseSizeBytes(fileInfo: string): number {
  const labeled = fileInfo.match(/size\s*[:=]\s*"?(\d+)/i);
  if (labeled) {
    return Number(labeled[1]);
  }
  const bytes = fileInfo.match(/(\d+)\s*bytes/i);
  return bytes ? Number(bytes[1]) : 0;
}

function gradeModule(
  sizeBytes: number,
  text: string
): "large" | "documented" | "plain" {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordGrade(grades: ModuleGrade[], path: string, grade: string) {
  grades.push({ path, grade });
}

function recordFailure(failures: string[], key: string, error: unknown) {
  failures.push(`${key}: ${String(error)}`);
}

function countGrades(
  grades: ModuleGrade[]
): { large: number; documented: number; plain: number } {
  const counts = { large: 0, documented: 0, plain: 0 };
  for (const entry of grades) {
    if (entry.grade === "large") {
      counts.large += 1;
    } else if (entry.grade === "documented") {
      counts.documented += 1;
    } else {
      counts.plain += 1;
    }
  }
  return counts;
}

function buildAuditReport(
  grades: ModuleGrade[],
  failures: string[],
  thoughtCount: number
): string {
  const lines: string[] = ["# Repository audit", "", "## module grades", ""];
  for (const entry of grades) {
    lines.push(`- ${entry.path}: ${entry.grade}`);
  }
  if (failures.length > 0) {
    lines.push("", "## unreadable modules", "");
    for (const failure of failures) {
      lines.push(`- ${failure}`);
    }
  }
  lines.push(
    "",
    "## reasoning",
    "",
    `Sequential thinking completed: ${thoughtCount} of 3 thoughts were taken and recorded.`,
    ""
  );
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [directorySizes, directoryTree, allowedDirectories] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories(),
  ]);

  const found = await tools.fs.searchFiles({
    path: input.root,
    pattern: "*.ts",
  });
  const modules = modulePaths(found.content);

  const grades: ModuleGrade[] = [];
  const failures: string[] = [];
  let visited = 0;

  for (const path of modules) {
    if (visited >= input.maxModules) {
      break;
    }

    try {
      const info = await tools.fs.getFileInfo({ path });
      const text = await tools.fs.readTextFile({ path });
      const sizeBytes = parseSizeBytes(info.content);
      const grade = gradeModule(sizeBytes, text.content);
      recordGrade(grades, path, grade);
    } catch (error) {
      recordFailure(failures, path, error);
    }

    visited += 1;
  }

  const thoughtOne = await tools.reasoning.sequentialThinking({
    thought: `Inventory gathered in parallel for ${input.root}: sized listing, recursive tree, and allowed directories. Found ${modules.length} TypeScript modules; graded up to ${input.maxModules} of them with ${failures.length} unreadable.`,
    nextThoughtNeeded: true,
    thoughtNumber: 1,
    totalThoughts: 3,
  });

  const thoughtTwo = await tools.reasoning.sequentialThinking({
    thought: `Grading breakdown so far: ${grades.filter((g) => g.grade === "large").length} large, ${grades.filter((g) => g.grade === "documented").length} documented, ${grades.filter((g) => g.grade === "plain").length} plain. Unreadable modules were recorded and skipped rather than aborting the audit.`,
    nextThoughtNeeded: true,
    thoughtNumber: 2,
    totalThoughts: 3,
  });

  const thoughtThree = await tools.reasoning.sequentialThinking({
    thought: `Audit conclusion: write audit.md with every module grade and a reasoning section noting all three thoughts, then report the per-grade counts. No further analysis needed.`,
    nextThoughtNeeded: false,
    thoughtNumber: 3,
    totalThoughts: 3,
  });

  const thoughts = [thoughtOne, thoughtTwo, thoughtThree];
  const thoughtCount = thoughts.length;

  const report = buildAuditReport(grades, failures, thoughtCount);
  await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report,
  });

  const counts = countGrades(grades);
  return { ...counts, thoughts: thoughtCount };
}

import type { Tools } from "../generated/tools";

type ModuleGrade = "large" | "documented" | "plain";
type ModuleRecord = { path: string; grade: ModuleGrade };

function parseSearchResults(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && line.endsWith(".ts"));
}

function takeFirst<T>(items: T[], max: number): T[] {
  return items.slice(0, Math.max(0, max));
}

function fileSizeOf(infoJson: string): number {
  try {
    const parsed = JSON.parse(infoJson) as { size?: number };
    return typeof parsed.size === "number" ? parsed.size : 0;
  } catch {
    return 0;
  }
}

function gradeModule(sizeBytes: number, text: string): ModuleGrade {
  if (sizeBytes > 200) return "large";
  if (text.includes("/**")) return "documented";
  return "plain";
}

function recordModule(records: ModuleRecord[], path: string, grade: ModuleGrade) {
  records.push({ path, grade });
}

function recordFailure(failures: string[], path: string, error: unknown) {
  failures.push(`${path}: ${String(error)}`);
}

function countGrades(records: ModuleRecord[]): Record<ModuleGrade, number> {
  const counts: Record<ModuleGrade, number> = { large: 0, documented: 0, plain: 0 };
  for (const record of records) counts[record.grade] += 1;
  return counts;
}

function describeGrades(counts: Record<ModuleGrade, number>): string {
  return `large=${counts.large}, documented=${counts.documented}, plain=${counts.plain}`;
}

function renderAudit(records: ModuleRecord[], thoughtCount: number): string {
  const lines: string[] = ["# Repository Audit", ""];
  for (const record of records) {
    lines.push(`- ${record.path}: ${record.grade}`);
  }
  lines.push("", "## reasoning", "", `${thoughtCount} sequential thoughts were taken during this audit.`);
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [sizeListing, tree, allowedRoots] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({})
  ]);

  const matches = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const foundModules = parseSearchResults(matches.content);
  const targetModules = takeFirst(foundModules, input.maxModules);

  const audited: ModuleRecord[] = [];
  const unreadable: string[] = [];

  for (const path of targetModules) {
    try {
      const fileInfo = await tools.fs.getFileInfo({ path });
      const sizeBytes = fileSizeOf(fileInfo.content);
      const fileContents = await tools.fs.readTextFile({ path });
      const grade = gradeModule(sizeBytes, fileContents.content);
      recordModule(audited, path, grade);
    } catch (error) {
      recordFailure(unreadable, path, error);
    }
  }

  const gradeCounts = countGrades(audited);
  const gradeLine = describeGrades(gradeCounts);

  const thoughtOne = await tools.reasoning.sequentialThinking({
    thought: `Inventory: ${foundModules.length} TypeScript modules matched, auditing ${targetModules.length} of them under ${input.root}; ${unreadable.length} could not be read. Grade mix so far: ${gradeLine}.`,
    thoughtNumber: 1,
    totalThoughts: 3,
    nextThoughtNeeded: true
  });

  const thoughtTwo = await tools.reasoning.sequentialThinking({
    thought: `Coverage analysis: ${gradeCounts.documented} of ${audited.length} graded modules carry /** documentation and ${gradeCounts.large} exceed 200 bytes; cross-checking these grades against the captured size listing and directory tree for gaps.`,
    thoughtNumber: 2,
    totalThoughts: 3,
    nextThoughtNeeded: true
  });

  const thoughtThree = await tools.reasoning.sequentialThinking({
    thought: `Verdict: ${audited.length} modules graded (${gradeLine}) with ${unreadable.length} recorded as unreadable; the hypothesis holds against the listing and tree, so the audit is complete.`,
    thoughtNumber: 3,
    totalThoughts: 3,
    nextThoughtNeeded: false
  });

  const thoughts = [thoughtOne, thoughtTwo, thoughtThree];

  const report = renderAudit(audited, thoughts.length);
  const written = await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report
  });

  return {
    grades: gradeCounts,
    thoughtsRecorded: thoughts.length
  };
}
